# Gene sets: four themes (MSigDB) + osteogenesis-related signaling pathways (curated)---------------------
source("R/00_config.R")
suppressPackageStartupMessages({
  library(AnnotationDbi)
  library(org.Rn.eg.db)
})
dir.create(out("02_gene_sets"), showWarnings = FALSE)

# Four theme gene sets ---------------------------------------------------------------
# Source: msigdbr(species = "Rattus norvegicus", category = "C5"); gene sets whose names match keywords are selected and merged
# Generated by 4pathways_SPMS_MS.Rmd and saved as all_acquired_genes.csv; it is read directly here,
# so that msigdbr updates cannot change the gene sets
gs4 <- read.csv(GENESET4_FILE)
theme_sets <- list(
  Cell_ECM            = unique(gs4$Genes[gs4$Pathway == "cell-ECM interaction"]),
  Cell_Cell           = unique(gs4$Genes[gs4$Pathway == "cell-cell interaction"]),
  Mechanotransduction = unique(gs4$Genes[gs4$Pathway == "mechanotransduction"]),
  Osteogenesis        = unique(gs4$Genes[gs4$Pathway == "osteogenesis"])
)

