signaling_sets <- lapply(signaling_sets, unique)

# Check gene names: official rat symbols in org.Rn.eg.db? present in the expression data? -------
res_list   <- load_rds("res_list")
expr_genes <- rownames(res_list[[MAIN_COMPARISON]])
rat_symbols <- keys(org.Rn.eg.db, keytype = "SYMBOL")

all_sets <- c(theme_sets, signaling_sets)
check <- do.call(rbind, lapply(names(all_sets), function(nm) {
  g <- all_sets[[nm]]
  data.frame(Pathway = nm, Gene = g,
             In_org.Rn.eg.db = g %in% rat_symbols,
             In_expression_data = g %in% expr_genes)
}))
write.csv(check, out("02_gene_sets", "gene_name_check.csv"), row.names = FALSE)

check_summary <- aggregate(cbind(In_org.Rn.eg.db, In_expression_data) ~ Pathway, data = check, FUN = sum)
check_summary$Total <- as.vector(table(check$Pathway)[check_summary$Pathway])
write.csv(check_summary, out("02_gene_sets", "gene_set_summary.csv"), row.names = FALSE)
print(check_summary)

bad <- check[!check$In_org.Rn.eg.db & check$Pathway %in% names(signaling_sets), ]
if (nrow(bad) > 0) {
  cat("\nCurated genes that are not official rat symbols:\n")
  print(bad[, c("Pathway", "Gene")], row.names = FALSE)
}

for (nm in names(signaling_sets)) {
  writeLines(signaling_sets[[nm]], out("02_gene_sets", paste0(nm, "_genes.txt")))
}

save_rds(list(theme = theme_sets, signaling = signaling_sets), "gene_sets")
